(() => {
  const results = Array.from(document.querySelectorAll('[data-component-type="s-search-result"]')).map((el,i)=>{
    const title = el.querySelector('h2 span')?.innerText?.trim() || '';
    const price = el.querySelector('.a-price .a-offscreen')?.innerText?.trim() || '';
    const reviewLink = el.querySelector('a[href*="#customerReviews"]');
    const reviews = reviewLink?.getAttribute('aria-label') || reviewLink?.innerText?.trim() || '';
    const rating = el.querySelector('[aria-label*="out of 5 stars"]')?.getAttribute('aria-label') || '';
    return {i:i+1, asin:el.getAttribute('data-asin'), title, price, reviews, rating};
  });
  return results.filter(r => /\b1\s*TB\b|\b1TB\b/i.test(r.title) && /SSD|Solid State/i.test(r.title) && !/HDD|Hard Drive HDD/i.test(r.title)).slice(0,20);
})()

(() => {
  const results = Array.from(document.querySelectorAll('[data-component-type="s-search-result"]')).map((el,i)=>{
    const title = el.querySelector('h2 span')?.innerText?.trim() || '';
    const price = el.querySelector('.a-price .a-offscreen')?.innerText?.trim() || '';
    const reviewLink = el.querySelector('a[href*="#customerReviews"]');
    const reviews = reviewLink?.getAttribute('aria-label') || reviewLink?.innerText?.trim() || '';
    const rating = el.querySelector('[aria-label*="out of 5 stars"]')?.getAttribute('aria-label') || '';
    return {i:i+1, asin:el.getAttribute('data-asin'), title, price, reviews, rating};
  });
  return results.filter(r => /(\b1\s*TB\b|\b1TB\b)/i.test(r.title) && /(SSD|Solid State)/i.test(r.title) && !/(HDD|Hard Drive HDD)/i.test(r.title)).slice(0,10);
})()

(() => {
  const candidates = Array.from(document.querySelectorAll('[data-component-type="s-search-result"]')).map((el,i)=>{
    const title = el.querySelector('h2 span')?.innerText?.trim() || '';
    const price = el.querySelector('.a-price .a-offscreen')?.innerText?.trim() || '';
    const reviewLink = el.querySelector('a[href*="#customerReviews"]');
    const reviews = reviewLink?.getAttribute('aria-label') || reviewLink?.innerText?.trim() || '';
    return {i:i+1, title, price, reviews};
  }).filter(r => /(\b1\s*TB\b|\b1TB\b)/i.test(r.title) && /(SSD|Solid State)/i.test(r.title) && /Portable|External/i.test(r.title) && !/HDD/i.test(r.title));
  return candidates.slice(0,5);
})()
